"""Generate a complete separate-origin trading document using the standard library.
Run: python python-trading-view.py OUTPUT_DIR
The host serves /program-trading-bootstrap.js; native controls confirm commands.
"""
from pathlib import Path
import sys

HTML = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trade Studio</title><link rel="stylesheet" href="trading.css"><script type="module" src="/program-trading-bootstrap.js"></script></head><body><main><header><h1 data-dc-trading-label="title"></h1><p data-dc-trading-label="description"></p></header><p role="status" data-dc-trading-status></p><section class="directory"><label><span data-dc-trading-label="find"></span><input type="search" maxlength="200" data-dc-trading-query="directory" disabled></label><button data-dc-trading-search data-dc-trading-label="search" type="button">Search</button><label><span data-dc-trading-label="choose"></span><select data-dc-trading-recipient disabled></select></label><button type="button" data-dc-trading-page="directory" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="directory" data-direction="1" data-dc-trading-label="more" disabled>more</button></section><div class="board"><section class="inventory"><h2 data-dc-trading-label="yourInventory"></h2><label><span data-dc-trading-label="searchOwn"></span><input type="search" maxlength="200" data-dc-trading-query="give" disabled></label><div class="cards" data-dc-trading-inventory="give"></div><p data-dc-trading-inventory-empty="give"></p><button type="button" data-dc-trading-page="give" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="give" data-direction="1" data-dc-trading-label="more" disabled>more</button><h3 data-dc-trading-label="youOffer"></h3><div class="tray" data-dc-trading-tray="give"></div></section><section class="inventory"><h2 data-dc-trading-label="theirInventory"></h2><label><span data-dc-trading-label="searchPartner"></span><input type="search" maxlength="200" data-dc-trading-query="receive" disabled></label><div class="cards" data-dc-trading-inventory="receive"></div><p data-dc-trading-inventory-empty="receive"></p><button type="button" data-dc-trading-page="receive" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="receive" data-direction="1" data-dc-trading-label="more" disabled>more</button><h3 data-dc-trading-label="youRequest"></h3><div class="tray" data-dc-trading-tray="receive"></div></section></div><section class="terms"><div data-dc-trading-currencies></div><button type="button" data-dc-trading-page="currencies" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="currencies" data-direction="1" data-dc-trading-label="more" disabled>more</button><label><span data-dc-trading-label="message"></span><textarea data-dc-trading-message maxlength="500" disabled></textarea></label><button type="button" data-dc-trading-command="draft-review" data-dc-trading-label="review" disabled>Review</button><button type="button" data-dc-trading-command="draft-clear" data-dc-trading-label="clear" disabled>Clear</button></section><section class="offers"><h2 data-dc-trading-label="offers"></h2><div data-dc-trading-offers></div><p data-dc-trading-offers-empty></p><button type="button" data-dc-trading-page="offers" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="offers" data-direction="1" data-dc-trading-label="more" disabled>more</button></section><section class="details" data-dc-trading-details hidden><h2 data-dc-trading-label="details"></h2><h3 data-dc-trading-label="senderOffers"></h3><div class="cards" data-dc-trading-detail-cards="give"></div><button type="button" data-dc-trading-page="detail-give" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="detail-give" data-direction="1" data-dc-trading-label="more" disabled>more</button><h3 data-dc-trading-label="senderRequests"></h3><div class="cards" data-dc-trading-detail-cards="receive"></div><button type="button" data-dc-trading-page="detail-receive" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="detail-receive" data-direction="1" data-dc-trading-label="more" disabled>more</button><div data-dc-trading-detail-currencies></div><button type="button" data-dc-trading-page="detail-currencies" data-direction="-1" data-dc-trading-label="previous" disabled>previous</button><button type="button" data-dc-trading-page="detail-currencies" data-direction="1" data-dc-trading-label="more" disabled>more</button></section></main><template data-dc-trading-card-template><article class="card"><img data-dc-card-preview alt="" hidden><strong data-dc-card-name></strong><span data-dc-card-line></span><span data-dc-card-rarity></span><p data-dc-card-reason></p><nav><button type="button" data-dc-card-inspect data-dc-trading-label="inspect" disabled>Inspect</button><button type="button" data-dc-card-add disabled>Add</button><button type="button" data-dc-card-remove data-dc-trading-label="remove" disabled>Remove</button></nav></article></template><template data-dc-trading-currency-template><article class="money"><strong data-dc-currency-name></strong><label><span data-dc-trading-label="offerCurrency"></span><input type="number" data-dc-currency-side="give" min="0" step="1" disabled></label><label><span data-dc-trading-label="requestCurrency"></span><input type="number" data-dc-currency-side="receive" min="0" step="1" disabled></label></article></template><template data-dc-trading-offer-template><article class="offer"><header><strong data-dc-offer-from></strong><span aria-hidden="true"> → </span><strong data-dc-offer-to></strong><span data-dc-offer-status></span></header><p data-dc-offer-message></p><p><span data-dc-trading-label="senderOffers"></span> / <span data-dc-trading-label="senderRequests"></span>: <span data-dc-offer-counts></span></p><small data-dc-offer-created></small><small data-dc-offer-expires></small><nav><button type="button" data-dc-offer-action="select" data-dc-trading-label="details" disabled>Details</button><button type="button" data-dc-offer-action="accept" data-dc-trading-label="accept" disabled>Accept</button><button type="button" data-dc-offer-action="counter" data-dc-trading-label="counter" disabled>Counter</button><button type="button" data-dc-offer-action="cancel" data-dc-trading-label="cancel" disabled>Cancel</button><button type="button" data-dc-offer-action="decline" data-dc-trading-label="decline" disabled>Decline</button></nav></article></template></body></html>'
CSS = '*{box-sizing:border-box}body{margin:0;font:16px system-ui,sans-serif;background:#edf4ef;color:#183c32}main{max-width:1200px;margin:auto;padding:24px}header{padding:16px;background:#d1e8d8}label{display:grid;gap:6px}input,select,textarea,button{font:inherit;padding:10px;border:1px solid #709681;border-radius:8px}button{background:#e0eee3;color:inherit;cursor:pointer}button:disabled{opacity:.5;cursor:default}nav,.directory,.money{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.directory,.terms,.offers,.details{margin:20px 0;padding:16px;border:1px solid #98b5a3;border-radius:16px}.board{display:grid;grid-template-columns:1fr 1fr;gap:24px}.cards,.tray{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;margin:12px 0}.card{display:grid;gap:6px;padding:12px;border:1px solid #afc7b8;background:white;border-radius:12px}.card img{width:100%;height:130px;object-fit:contain}.card[data-dc-selected=true],.offer[data-dc-selected=true]{outline:2px solid #246c49}.offer{padding:14px;margin:12px 0;background:white}.offer small{display:block}.money{margin:10px 0}textarea{width:100%;min-height:80px}:focus-visible{outline:3px solid #bc7b18;outline-offset:3px}[hidden]{display:none!important}@media(max-width:650px){main{padding:12px}.board{grid-template-columns:1fr}.cards,.tray{grid-template-columns:repeat(2,minmax(0,1fr))}}'

if __name__ == '__main__':
    if len(sys.argv) != 2:
        raise SystemExit('Usage: python python-trading-view.py OUTPUT_DIR')
    output = Path(sys.argv[1])
    output.mkdir(parents=True, exist_ok=True)
    (output / 'index.html').write_text(HTML, encoding='utf-8')
    (output / 'trading.css').write_text(CSS, encoding='utf-8')
